import threading

PAGES = {
    "home.html": "<h1>Hi</h1>",
    "news.html": "<p>Python</p>",
    "empty.html": "",
}


def download(url, sizes):
    # Giả lập tải trang (cấp sẵn): ngoài đời đây là lúc chờ mạng.
    sizes[url] = len(PAGES.get(url, ""))


def download_all(urls):
    sizes = {}
